{"command":"python3 - << 'PY'
rows=[list(l) for l in open("maze.txt").read().splitlines()]
R,C=len(rows),len(rows[0])
start=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=="@")
end=next((i,j) for i,row in enumerate(rows) for j,ch in enumerate(row) if ch=="E")
from collections import deque

def flood(src, blocked="#"):
    q=deque([src]); seen={src}
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    while q:
        r,c=q.popleft()
        for dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc]!=blocked and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen

A=flood(start)
B=flood(end)
print(len(A), len(B), "overlap", len(A&B))

# For each wall cell, see if removing it connects A to B
connectors=[]
for i in range(R):
    for j in range(C):
        if rows[i][j]!="#":
            continue
        # neighbors in A and B?
        dirs=[(-1,0),(1,0),(0,-1),(0,1)]
        touchA=touchB=False
        for dr,dc in dirs:
            nr,nc=i+dr,j+dc
            if (nr,nc) in A: touchA=True
            if (nr,nc) in B: touchB=True
        if touchA and touchB:
            connectors.append((i,j))
print("single wall connectors", len(connectors))
print(connectors[:50], "..." if len(connectors)>50 else "")

# also 2-wall gaps: walls adjacent to A, then wall, then B — list shortest bridge
# BFS through walls with cost 1 for wall, 0 for open in A, find min walls to reach B
# Actually from all A frontier, BFS allowing wall steps, count walls.
q=deque()
dist={}
for cell in A:
    dist[cell]=0
    q.append(cell)
dirs=[(-1,0),(1,0),(0,-1),(0,1)]
best=None
parent={}
while q:
    r,c=q.popleft()
    if (r,c) in B and (r,c) not in A:
        best=(r,c); break
    for dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if not (0<=nr<R and 0<=nc<C):
            continue
        # can step onto anything except maybe outer? allow all non already
        if (nr,nc) in dist:
            continue
        # cost: if wall, +1, else 0 — use 0-1 BFS
        cost = 1 if rows[nr][nc]=="#" else 0
        nd = dist[(r,c)] + cost
        dist[(nr,nc)] = nd
        parent[(nr,nc)]=(r,c)
        if cost==0:
            q.appendleft((nr,nc))
        else:
            q.append((nr,nc))
print("best entry into B", best, "wallcost", dist.get(best) if best else None)
# reconstruct
if best:
    cur=best
    path=[cur]
    while cur in parent and cur not in A:
        cur=parent[cur]
        path.append(cur)
    path.reverse()
    print("bridge path:")
    for p in path:
        print(p, rows[p[0]][p[1]], "cost", dist[p])
