rows=[list(l.rstrip("\n")) for l in open("maze.txt")]
H,W=len(rows),len(rows[0])
start=next((i,j) for i,r in enumerate(rows) for j,c in enumerate(r) if c=="@")
end=next((i,j) for i,r in enumerate(rows) for j,c in enumerate(r) if c=="E")
from collections import deque
def reaches(wrap=False, diag=False):
    q=deque([start]); prev={start:None}
    moves=[(-1,0),(1,0),(0,-1),(0,1)]
    if diag:
        moves += [(-1,-1),(-1,1),(1,-1),(1,1)]
    while q:
        r,c=q.popleft()
        if (r,c)==end: return True
        for dr,dc in moves:
            nr,nc=r+dr,c+dc
            if wrap:
                nr%=H; nc%=W
            if 0<=nr<H and 0<=nc<W and rows[nr][nc]!="#" and (nr,nc) not in prev:
                prev[(nr,nc)]=(r,c); q.append((nr,nc))
    return False
print("4", reaches())
print("wrap", reaches(wrap=True))
print("diag", reaches(diag=True))
print("wrapdiag", reaches(True, True))
# knight moves?
def knight():
    q=deque([start]); seen={start}
    moves=[(a,b) for a in (-2,-1,1,2) for b in (-2,-1,1,2) if abs(a)!=abs(b)]
    while q:
        r,c=q.popleft()
        if (r,c)==end: return True
        for dr,dc in moves:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and rows[nr][nc]!="#" and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return False
print("knight", knight())
