        s_n=[p for p in ns if p in Ds]
        e_n=[p for p in ns if p in De]
        if s_n and e_n:
            # path length = min Ds + 1 + min De + ? wait from s_n through wall to e_n
            # only if s_n and e_n are opposite, i.e. the wall is between them (they are not the same side)
            for a in s_n:
